package com.axiom.application.testreport;import com.axiom.domain.test.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;class TestStabilityServiceTest{@Test void conservativeClasses(){var s=new TestStabilityService();assertThat(s.classify(List.of(TestStatus.FAILED),0,0).classification()).isEqualTo(TestStabilityClass.INSUFFICIENT_HISTORY);assertThat(s.classify(Collections.nCopies(20,TestStatus.PASSED),0,0).classification()).isEqualTo(TestStabilityClass.STABLE);assertThat(s.classify(Arrays.asList(TestStatus.PASSED,TestStatus.PASSED,TestStatus.PASSED,TestStatus.PASSED,TestStatus.FAILED),1,0).classification()).isEqualTo(TestStabilityClass.SUSPECTED_FLAKY);}}
